/* eslint-disable no-restricted-globals */
// Codetry Practitioner's Handbook — offline service worker.
// Generated by build.js. Do not edit by hand; the precache list and cache
// version are written in at build time.

const CACHE_VERSION = "__CACHE_VERSION__";
const CACHE_NAME = "codetry-handbook-" + CACHE_VERSION;
const BASE_PATH = "__BASE_PATH__";
const PRECACHE = __PRECACHE_LIST__;
const NAVIGATION_FALLBACK = "__NAVIGATION_FALLBACK__";

self.addEventListener("install", function (event) {
  event.waitUntil(
    caches.open(CACHE_NAME).then(function (cache) {
      return cache.addAll(PRECACHE);
    }).then(function () {
      return self.skipWaiting();
    }),
  );
});

self.addEventListener("activate", function (event) {
  event.waitUntil(
    caches.keys().then(function (keys) {
      return Promise.all(
        keys
          .filter(function (key) {
            return key.indexOf("codetry-handbook-") === 0 && key !== CACHE_NAME;
          })
          .map(function (key) {
            return caches.delete(key);
          }),
      );
    }).then(function () {
      return self.clients.claim();
    }),
  );
});

function inScope(url) {
  return url.origin === self.location.origin && url.pathname.indexOf(BASE_PATH) === 0;
}

self.addEventListener("fetch", function (event) {
  var request = event.request;
  if (request.method !== "GET") return;

  var url;
  try {
    url = new URL(request.url);
  } catch (err) {
    return;
  }
  if (!inScope(url)) return;

  // Navigation requests: try the network first, fall back to cached shell.
  if (request.mode === "navigate") {
    event.respondWith(
      fetch(request)
        .then(function (response) {
          var copy = response.clone();
          caches.open(CACHE_NAME).then(function (cache) {
            cache.put(NAVIGATION_FALLBACK, copy).catch(function () {});
          });
          return response;
        })
        .catch(function () {
          return caches.match(NAVIGATION_FALLBACK).then(function (cached) {
            return cached || new Response("Offline and no cached copy available.", {
              status: 503,
              headers: { "content-type": "text/plain; charset=utf-8" },
            });
          });
        }),
    );
    return;
  }

  // Static assets: cache-first, then network, then cache the response.
  event.respondWith(
    caches.match(request).then(function (cached) {
      if (cached) return cached;
      return fetch(request)
        .then(function (response) {
          if (response && response.status === 200 && response.type === "basic") {
            var copy = response.clone();
            caches.open(CACHE_NAME).then(function (cache) {
              cache.put(request, copy).catch(function () {});
            });
          }
          return response;
        })
        .catch(function () {
          return caches.match(NAVIGATION_FALLBACK);
        });
    }),
  );
});
